-- Rice Settings (Super+Shift+/ or the cheat sheet's Settings button) edits these lines
local lock_on_login = true
local osu_auto_game_mode = true
local japanese_workspaces = true
local animated_border = true

-- Restore the screen gamma picked in Rice Settings (wl-gammactl has to keep running to hold it)
hl.on("hyprland.start", function() hl.exec_cmd(os.getenv("HOME") .. "/.local/bin/rice-settings apply-gamma") end)

-- Keep the monitor layout generated by nwg-displays.
require("monitors")

-- Route wine/gamemd/Mental Omega/Syringe windows to laptop monitor (workspace 2 on eDP-1)
hl.window_rule({
    match = { class = ".*[Gg]amemd.*|.*[Ss]yringe.*|.*[Ww]ine.*" },
    workspace = "2",
})
hl.window_rule({
    match = { title = ".*[Yy]uri.*|.*Fatal Error.*|.*Mental Omega.*|.*gamemd.*" },
    workspace = "2",
})


-- Keybind cheat sheet (~/.config/quickshell/cheatsheet)
hl.bind("SUPER + Slash", hl.dsp.global("cheatsheet:toggle"))
hl.on("hyprland.start", function()
    hl.exec_cmd("quickshell -p " .. os.getenv("HOME") .. "/.config/quickshell/cheatsheet -n -d")
end)

-- Frosted glass blur: keep colour behind the glass, add a little grain
hl.config({ decoration = { blur = { vibrancy = 0.25, noise = 0.03, contrast = 1.0, brightness = 1.0 } } })

-- Frosted glass behind the shell (bar, drawers). ignore_alpha skips the fully clear parts of the overlay.
hl.layer_rule({ match = { namespace = "caelestia-drawers" }, blur = true, ignore_alpha = 0.3 })

-- osu!: focus it -> Caelestia game mode (no blur/anims/gaps/shadows); the shell already hides bar+border for fullscreen.
-- Only turns game mode off again if this hook turned it on.
local osu_game_mode = false
hl.on("window.active", function(win)
    local is_osu = win ~= nil and win.class == "osu!"
    if osu_auto_game_mode and is_osu ~= osu_game_mode then
        osu_game_mode = is_osu
        hl.exec_cmd("caelestia shell gameMode " .. (is_osu and "enable" or "disable"))
    end
end)

-- kitty: clear glass, no blur (wallpaper stays sharp behind the terminal)
hl.window_rule({ match = { class = "kitty" }, no_blur = true })

-- Bar: Super+B shows it (windows make room) and it hides itself after 60s; Super+B again hides it now.
-- Hovering the left edge still peeks it over windows.
hl.bind("SUPER + B", hl.dsp.exec_cmd(os.getenv("HOME") .. "/.local/bin/bar-peek"))
hl.on("hyprland.start", function()
    hl.exec_cmd("sh -c 'sleep 3; " .. os.getenv("HOME") .. "/.local/bin/bar-peek'")
end)

-- Game mode toggle (same as the toggle in the utilities panel)
hl.bind("SUPER + G", hl.dsp.exec_cmd("caelestia shell gameMode toggle"))

-- Lock on login (greetd auto-logs in, see /etc/nixos/autologin.nix).
-- The shell takes a moment to start, so keep asking until it reports locked (gives up after ~60s).
if lock_on_login then hl.on("hyprland.start", function()
    hl.exec_cmd([[sh -c 'for i in $(seq 300); do caelestia shell lock lock >/dev/null 2>&1; [ "$(caelestia shell lock isLocked 2>/dev/null)" = true ] && exit; sleep 0.2; done']])
end) end

-- Animations: windows pop in with a slight overshoot, workspaces slide vertically (matches the vertical bar)
hl.curve("overshot", { type = "bezier", points = { { 0.34, 1.4 }, { 0.64, 1 } } })
hl.animation({ leaf = "windowsIn", enabled = true, speed = 5, bezier = "overshot", style = "popin 85%" })
hl.animation({ leaf = "windowsOut", enabled = true, speed = 3, bezier = "emphasizedAccel", style = "popin 85%" })
hl.animation({ leaf = "workspaces", enabled = true, speed = 5, bezier = "standard", style = "slidevert" })

-- Super+Shift+W: switch the >wallpaper picker between the normal and questionable folders (~/.local/bin/wallpaper-mode)
hl.bind("SUPER + SHIFT + W", hl.dsp.exec_cmd(os.getenv("HOME") .. "/.local/bin/wallpaper-mode"))

-- Japanese workspace numbers (一…十) in the bar: Caelestia shows a workspace's name instead of its
-- number, and persistent keeps empty workspaces around so they show it too. Rice Settings flips this.
local kanji = { "一", "二", "三", "四", "五", "六", "七", "八", "九", "十" }
for i = 1, 10 do
    local name = japanese_workspaces and kanji[i] or tostring(i)
    hl.workspace_rule({ workspace = tostring(i), persistent = japanese_workspaces, default_name = name })
    -- Rules only name new workspaces; rename the ones that already exist (on reload)
    pcall(hl.dispatch, hl.dsp.workspace.rename({ workspace = tostring(i), name = name }))
end

-- Rice settings page of the cheat sheet (also reachable from its Settings button)
hl.bind("SUPER + SHIFT + Slash", hl.dsp.global("cheatsheet:settings"))

-- Cheat sheet / settings card: blurred glass, but ignore_alpha turns the blur off when the card fades
-- to 0.2 while a slider is dragged, so you see the desktop change live (card alpha in shell.qml)
hl.layer_rule({ match = { namespace = "cheatsheet" }, blur = true, ignore_alpha = 0.3 })

-- Dolphin: clear glass like kitty. The Darkly Qt style makes only the backgrounds see-through
-- (~/.config/darklyrc); no blur here so the wallpaper stays sharp behind it.
hl.window_rule({ match = { class = "org.kde.dolphin" }, no_blur = true })

-- Animated border: the focused window's border is a slowly turning blue -> sky -> violet gradient
-- (scheme colours, so it follows >scheme). Rice Settings flips animated_border.
if animated_border then
    local scheme = require("scheme.current")
    hl.config({ general = { col = { active_border = { angle = 45, colors = {
        "rgba(" .. scheme.primary .. "ff)", "rgba(" .. scheme.tertiary .. "ff)", "rgba(9d7cd8ff)", "rgba(" .. scheme.primary .. "ff)" } } } } })
    hl.curve("linear", { type = "bezier", points = { { 0, 0 }, { 1, 1 } } })
    hl.animation({ leaf = "borderangle", enabled = true, speed = 100, bezier = "linear", style = "loop" })
end

-- Night light: hyprsunset follows ~/.config/hypr/hyprsunset.conf (Settings > Night light writes it).
-- Replaces the gammastep line in Caelestia's execs.lua, which isn't installed on this system.
hl.on("hyprland.start", function() hl.exec_cmd("hyprsunset") end)

-- Do Not Disturb (Super+N is the notification sidebar, so Shift adds "be quiet"); also in Settings
hl.bind("SUPER + SHIFT + N", hl.dsp.exec_cmd("caelestia shell notifs toggleDnd"))
